package com.rohit.inventory.controller;
import com.rohit.inventory.dto.request.*; import com.rohit.inventory.dto.response.*; import com.rohit.inventory.service.InventoryService; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/inventory") public class InventoryController { private final InventoryService service; public InventoryController(InventoryService service){this.service=service;} @GetMapping @PreAuthorize("hasAuthority('INVENTORY_READ')") public ApiResponse<Page<InventoryResponse>> list(@PageableDefault(size=20,sort="updatedAt",direction=Sort.Direction.DESC) Pageable p){return ApiResponse.success("Inventory retrieved successfully",service.list(p));} @GetMapping("/{id}") @PreAuthorize("hasAuthority('INVENTORY_READ')") public ApiResponse<InventoryResponse> get(@PathVariable UUID id){return ApiResponse.success("Inventory retrieved successfully",service.get(id));} @PostMapping("/stock-in") @PreAuthorize("hasAuthority('INVENTORY_ADJUST')") public ApiResponse<InventoryResponse> in(@Valid @RequestBody StockMovementRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Stock received successfully",service.stockIn(r,u.getUsername()));} @PostMapping("/stock-out") @PreAuthorize("hasAuthority('INVENTORY_ADJUST')") public ApiResponse<InventoryResponse> out(@Valid @RequestBody StockMovementRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Stock issued successfully",service.stockOut(r,u.getUsername()));} @PostMapping("/adjust") @PreAuthorize("hasAuthority('INVENTORY_ADJUST')") public ApiResponse<InventoryResponse> adjust(@Valid @RequestBody StockAdjustmentRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Stock adjusted successfully",service.adjust(r,u.getUsername()));} @PostMapping("/reserve") @PreAuthorize("hasAuthority('INVENTORY_ADJUST')") public ApiResponse<InventoryResponse> reserve(@Valid @RequestBody StockMovementRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Stock reserved successfully",service.reserve(r,u.getUsername()));} @PostMapping("/release") @PreAuthorize("hasAuthority('INVENTORY_ADJUST')") public ApiResponse<InventoryResponse> release(@Valid @RequestBody StockMovementRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Stock released successfully",service.release(r,u.getUsername()));} @GetMapping("/transactions") @PreAuthorize("hasAuthority('INVENTORY_READ')") public ApiResponse<Page<InventoryTransactionResponse>> history(@RequestParam UUID warehouseId,@RequestParam UUID zoneId,@RequestParam UUID productId,@PageableDefault(size=20,sort="occurredAt",direction=Sort.Direction.DESC) Pageable p){return ApiResponse.success("Inventory transactions retrieved successfully",service.history(warehouseId,zoneId,productId,p));} }
